    if (error instanceof ApiRequestError && error.status === 401) {
      try {
        await refreshSession()
        await connectOnce(payload, handlers)
        return
      } catch (retryError) {
        if (retryError instanceof ApiRequestError && retryError.status === 401) {
          notifyUnauthorized()
        }
        throw retryError
      }
    }
    throw error
  }
}
"}

