        onOpen: (runId) => {
          if (runId) firstRunId = runId
        },
        onEvent: (event, data) => {
          const record = data as Record<string, unknown>
          firstEvents.push({ event, data: record })
          if (event === 'conversation.created' && typeof record.conversation_id === 'string') {
